// Pose-keyed AF-ON profile codec. Pure. No storage key and no cell index.
// Zone and position are stored for landscape, then EXIF 6, then EXIF 8.
// The reader maps a pose onto a settings cell. This module does not.
// Dimension and step slots are the shared custom-table indices.
// Version 2: zero is in the custom domains, so horizontal step is 4 bits.
// A failed marker, version, checksum, spare, padding, or range check decodes
// as null ("no profile"). Encode throws RangeError. It does not clamp.
// Do not edit this file after it has run.

export const RECORD_BYTES = 26;
export const MARKER = 0xa70f;
export const VERSION = 2;
export const POSITION_MAX = 1052;
export const POSES = ['landscape', 'exif6', 'exif8'];

// Descriptor order. Zero is first only where the descriptor table omitted it.
export const ZONE = [0, 1, 2, 3, 5, 10, 6, 7, 8, 9];
export const DIM_V = [0, 1, 3, 5, 7, 9, 11, 15, 19, 23, 27];
export const DIM_H = [0, 1, 3, 5, 7, 9, 11, 15, 19, 23, 27, 33, 39];
export const STEP_V = [0, 1, 2, 3, 4, 5];
export const STEP_H = [0, 1, 2, 3, 4, 5, 6, 7, 8];

export const ZONE_BITS = 4;
export const SIZE_BITS = 8;
export const POSITION_BITS = 11;
export const DIM_V_BITS = 4;
export const DIM_H_BITS = 4;
export const STEP_V_BITS = 3;
export const STEP_H_BITS = 4;

export const PAYLOAD_BITS = 121;
export const MARKER_BITS = 16;
export const VERSION_BITS = 8;
export const FIELD_BITS = 145;
export const PAD_BITS = 7;
export const CRC_BITS = 16;
export const USED_BITS = 168;
export const USED_BYTES = 21;
export const SPARE_BITS = 40;

const DIM_V_INDEX = [0, 2, 4, 6, 8];
const DIM_H_INDEX = [1, 3, 5, 7, 9];
const STEP_V_INDEX = [0, 2, 4, 6];
const STEP_H_INDEX = [1, 3, 5, 7];

function bitsForCount(n) {
  let w = 0;
  while ((1 << w) < n) w += 1;
  return w;
}
if (bitsForCount(ZONE.length) !== ZONE_BITS) throw new Error('zone bits');
if (bitsForCount(DIM_V.length) !== DIM_V_BITS) throw new Error('dim v bits');
if (bitsForCount(DIM_H.length) !== DIM_H_BITS) throw new Error('dim h bits');
if (bitsForCount(STEP_V.length) !== STEP_V_BITS) throw new Error('step v bits');
if (bitsForCount(STEP_H.length) !== STEP_H_BITS) throw new Error('step h bits');
if (POSITION_MAX >= (1 << POSITION_BITS)) throw new Error('position bits');
const payloadCheck = ZONE_BITS * POSES.length + SIZE_BITS + POSITION_BITS * POSES.length
  + DIM_V_BITS * DIM_V_INDEX.length + DIM_H_BITS * DIM_H_INDEX.length
  + STEP_V_BITS * STEP_V_INDEX.length + STEP_H_BITS * STEP_H_INDEX.length;
if (payloadCheck !== PAYLOAD_BITS) throw new Error('payload ' + payloadCheck);
if (MARKER_BITS + VERSION_BITS + PAYLOAD_BITS !== FIELD_BITS) throw new Error('field');
if ((8 - (FIELD_BITS % 8)) % 8 !== PAD_BITS) throw new Error('pad');
if (FIELD_BITS + PAD_BITS + CRC_BITS !== USED_BITS) throw new Error('used bits');
if (USED_BITS !== USED_BYTES * 8) throw new Error('used bytes');
if (RECORD_BYTES * 8 - USED_BITS !== SPARE_BITS) throw new Error('spare');

function poseMap(map, name) {
  if (!map || typeof map !== 'object') throw new RangeError(name);
  if (Object.keys(map).length !== POSES.length) throw new RangeError(name);
  for (const pose of POSES) if (!Object.hasOwn(map, pose)) throw new RangeError(name);
  return map;
}

function codeOf(table, value, width, name) {
  if (!Number.isInteger(value)) throw new RangeError(name);
  const code = table.indexOf(value);
  if (code < 0 || code >= (1 << width)) throw new RangeError(name);
  return code;
}

function valueOf(table, code, width) {
  if (!Number.isInteger(code) || code < 0 || code >= (1 << width) || code >= table.length) return null;
  return table[code];
}

function writeBits(buf, pos, value, width) {
  for (let i = 0; i < width; i++) {
    if ((value >>> i) & 1) buf[(pos + i) >> 3] |= 1 << ((pos + i) & 7);
  }
  return pos + width;
}

function readBits(buf, pos, width) {
  let value = 0;
  for (let i = 0; i < width; i++) {
    if (buf[(pos + i) >> 3] & (1 << ((pos + i) & 7))) value |= 1 << i;
  }
  return value;
}

export function crc16(bytes) {
  let crc = 0xffff;
  for (const b of bytes) {
    crc ^= b;
    for (let i = 0; i < 8; i++) crc = (crc & 1) ? ((crc >>> 1) ^ 0xa001) : (crc >>> 1);
  }
  return crc & 0xffff;
}

function pack(profile) {
  const zone = poseMap(profile.zone, 'zone');
  const position = poseMap(profile.position, 'position');
  if (!Number.isInteger(profile.size) || profile.size < 0 || profile.size > 255) throw new RangeError('size');
  const buf = new Uint8Array(RECORD_BYTES);
  let p = 0;
  p = writeBits(buf, p, MARKER, MARKER_BITS);
  p = writeBits(buf, p, VERSION, VERSION_BITS);
  for (const pose of POSES) p = writeBits(buf, p, codeOf(ZONE, zone[pose], ZONE_BITS, 'zone ' + pose), ZONE_BITS);
  p = writeBits(buf, p, profile.size, SIZE_BITS);
  for (const pose of POSES) {
    const v = position[pose];
    if (!Number.isInteger(v) || v < 0 || v > POSITION_MAX) throw new RangeError('position ' + pose);
    p = writeBits(buf, p, v, POSITION_BITS);
  }
  for (const index of DIM_V_INDEX) {
    p = writeBits(buf, p, codeOf(DIM_V, profile.dim[index], DIM_V_BITS, 'dim ' + index), DIM_V_BITS);
  }
  for (const index of DIM_H_INDEX) {
    p = writeBits(buf, p, codeOf(DIM_H, profile.dim[index], DIM_H_BITS, 'dim ' + index), DIM_H_BITS);
  }
  for (const index of STEP_V_INDEX) {
    p = writeBits(buf, p, codeOf(STEP_V, profile.step[index], STEP_V_BITS, 'step ' + index), STEP_V_BITS);
  }
  for (const index of STEP_H_INDEX) {
    p = writeBits(buf, p, codeOf(STEP_H, profile.step[index], STEP_H_BITS, 'step ' + index), STEP_H_BITS);
  }
  if (p !== FIELD_BITS) throw new Error('field bits ' + p);
  p += PAD_BITS;
  if (p !== USED_BYTES * 8 - CRC_BITS) throw new Error('pad');
  const crc = crc16(buf.subarray(0, USED_BYTES - 2));
  p = writeBits(buf, p, crc, CRC_BITS);
  if (p !== USED_BITS) throw new Error('used');
  return buf;
}

export function encode(profile) {
  if (!profile || typeof profile !== 'object') throw new RangeError('profile');
  if (!Array.isArray(profile.dim) || profile.dim.length !== 10) throw new RangeError('profile');
  if (!Array.isArray(profile.step) || profile.step.length !== 8) throw new RangeError('profile');
  return pack(profile);
}

export function decode(bytes) {
  if (!bytes || bytes.length !== RECORD_BYTES) return null;
  const buf = Uint8Array.from(bytes);
  for (let i = USED_BYTES; i < RECORD_BYTES; i++) if (buf[i] !== 0) return null;
  for (let bit = FIELD_BITS; bit < FIELD_BITS + PAD_BITS; bit++) {
    if (buf[bit >> 3] & (1 << (bit & 7))) return null;
  }
  if (readBits(buf, FIELD_BITS + PAD_BITS, CRC_BITS) !== crc16(buf.subarray(0, USED_BYTES - 2))) return null;
  let p = 0;
  if (readBits(buf, p, MARKER_BITS) !== MARKER) return null;
  p += MARKER_BITS;
  if (readBits(buf, p, VERSION_BITS) !== VERSION) return null;
  p += VERSION_BITS;
  const zone = {};
  for (const pose of POSES) {
    const v = valueOf(ZONE, readBits(buf, p, ZONE_BITS), ZONE_BITS);
    if (v === null) return null;
    zone[pose] = v;
    p += ZONE_BITS;
  }
  const size = readBits(buf, p, SIZE_BITS);
  p += SIZE_BITS;
  const position = {};
  for (const pose of POSES) {
    const v = readBits(buf, p, POSITION_BITS);
    if (v > POSITION_MAX) return null;
    position[pose] = v;
    p += POSITION_BITS;
  }
  const dim = new Array(10);
  for (const index of DIM_V_INDEX) {
    const v = valueOf(DIM_V, readBits(buf, p, DIM_V_BITS), DIM_V_BITS);
    if (v === null) return null;
    dim[index] = v;
    p += DIM_V_BITS;
  }
  for (const index of DIM_H_INDEX) {
    const v = valueOf(DIM_H, readBits(buf, p, DIM_H_BITS), DIM_H_BITS);
    if (v === null) return null;
    dim[index] = v;
    p += DIM_H_BITS;
  }
  const step = new Array(8);
  for (const index of STEP_V_INDEX) {
    const v = valueOf(STEP_V, readBits(buf, p, STEP_V_BITS), STEP_V_BITS);
    if (v === null) return null;
    step[index] = v;
    p += STEP_V_BITS;
  }
  for (const index of STEP_H_INDEX) {
    const v = valueOf(STEP_H, readBits(buf, p, STEP_H_BITS), STEP_H_BITS);
    if (v === null) return null;
    step[index] = v;
    p += STEP_H_BITS;
  }
  if (p !== FIELD_BITS) return null;
  return { zone, size, position, dim, step };
}

// T10 profile A, named by pose. landscape was bank 1, exif6 bank 5, exif8 bank 3.
export const PROFILE_A = {
  zone: { landscape: 2, exif6: 6, exif8: 1 },
  size: 0,
  position: { landscape: 529, exif6: 532, exif8: 418 },
  dim: [1, 1, 5, 7, 1, 3, 9, 11, 15, 33],
  step: [5, 8, 1, 2, 3, 4, 4, 1],
};
